const {chromium}=require('playwright'),fs=require('fs'),os=require('os'),path=require('path'),http=require('http'),assert=require('assert/strict'),{execFileSync}=require('child_process');
const repo=path.resolve(__dirname,'../..'),dir=fs.mkdtempSync(path.join(os.tmpdir(),'sambaadm-search-'));
execFileSync('go',['test','./internal/web','-run','^TestWorkspaceBrowserFixtures$','-count=1'],{cwd:repo,env:{...process.env,SAMBAADM_WEB_FIXTURE_DIR:dir}});
const server=http.createServer((req,res)=>{const p=new URL(req.url,'http://localhost').pathname,file=p.startsWith('/static/')?path.join(repo,'internal/web',p):path.join(dir,'admin-'+p.slice(1).replaceAll('/','_')+'.html');if(!fs.existsSync(file)){res.writeHead(404).end();return;}res.setHeader('Content-Type',file.endsWith('.js')?'application/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file));});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true});try{const page=await browser.newPage({viewport:{width:1440,height:1000}}),errors=[];page.on('pageerror',e=>errors.push(e.message));const guid='{11111111-1111-1111-1111-111111111111}',dn='CN=RODC Allowed Accounts,OU=Филиал,DC=example,DC=com';await page.route('**/api/v1/**',async route=>{const u=new URL(route.request().url()),p=u.pathname.slice(7);let json=[];if(p==='/gpo')json=[{guid,displayName:'Политика сотрудников',source:'ldap'}];else if(p==='/gpo/'+encodeURIComponent(guid)||decodeURIComponent(p)==='/gpo/'+guid)json='displayName: Политика сотрудников\nflags: 1\nversionNumber: 65552\ndn: CN='+guid+',CN=Policies,CN=System,DC=example,DC=com';else if(p==='/sites/controllers')json=[{dns:'rodc1.example.com',site:'Филиал',rodc:true}];else if(p.endsWith('/rodc'))json={controller:{dns:'rodc1.example.com',site:'Филиал'},source:'dc0.example.com',allowed:[{name:'Allowed RODC Password Replication Group',kind:'group',dn}],denied:[{name:'Domain Admins',kind:'group',dn:'CN=Domain Admins,DC=example,DC=com'}],cached:[],authenticated:[],preloadAvailable:false};else if(p==='/directory/tree')json={kind:'domain',dn:'DC=example,DC=com',label:'example.com',children:[]};await route.fulfill({json});});const base='http://127.0.0.1:'+server.address().port;
await page.goto(base+'/gpo');await page.getByRole('button',{name:'Свойства',exact:true}).click();const dialog=page.getByRole('dialog');await dialog.getByRole('heading',{name:'Политика сотрудников',exact:true}).waitFor();assert.equal(await dialog.getByText('Отключена',{exact:true}).count(),1);assert.equal(await dialog.locator('details.gpo-property-technical').evaluate(e=>e.open),false);assert.equal(await page.locator('tbody .row-actions').count(),0);await page.screenshot({path:path.join(dir,'gpo-property-card.png'),fullPage:true});await dialog.getByRole('button',{name:'Закрыть окно',exact:true}).click();
await page.goto(base+'/sites');await page.getByRole('button',{name:'Кэш RODC',exact:true}).click();await dialog.getByLabel('Контроллер RODC',{exact:true}).selectOption('rodc1.example.com');await dialog.getByText('Allowed RODC Password Replication Group',{exact:true}).waitFor();assert.equal(await dialog.getByText('Группа',{exact:true}).count(),2);assert.equal(await dialog.getByText('group',{exact:true}).count(),0);assert.equal(await dialog.locator('.rodc-path').first().evaluate(e=>e.open),false);await page.screenshot({path:path.join(dir,'rodc-permissions.png'),fullPage:true});await dialog.getByRole('button',{name:'Кэш и обращения',exact:true}).click();await dialog.getByRole('heading',{name:'Пароли закэшированы на этом RODC',exact:true}).waitFor();await dialog.getByRole('button',{name:'Разрешения',exact:true}).click();await page.setViewportSize({width:390,height:844});await dialog.locator('.rodc-path summary').first().click();assert.equal(await dialog.evaluate(e=>e.scrollWidth>e.clientWidth),false);await page.screenshot({path:path.join(dir,'rodc-mobile.png'),fullPage:true});await dialog.getByRole('button',{name:'Закрыть окно',exact:true}).click();await page.setViewportSize({width:1440,height:1000});
await page.goto(base+'/diagnostics');await page.getByRole('heading',{name:'Параметры проверки',exact:true}).waitFor();assert(await page.locator('.diagnostics-controls').evaluate(e=>e.getBoundingClientRect().width<=1050));await page.getByRole('heading',{name:'Проверки ещё не запускались',exact:true}).waitFor();await page.screenshot({path:path.join(dir,'diagnostics-options.png'),fullPage:true});await page.setViewportSize({width:390,height:844});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.deepEqual(errors,[]);console.log('PASS GPO properties and actions, RODC tabs and translated types, hidden DN, diagnostics layout, mobile. Screenshots:',dir);}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
